@startuml

class Car {
  + licensePlate : string
}

class Owner {
  + name : string
}

class Accident {
  + date : date
  + location : string
  + damageAmount : double
}

class RideHailService {
  + pickUpTime : datetime
  + dropOffTime : datetime
  + pickUpLocation : string
  + dropOffLocation : string
  + rideDuration : string
  + distance : double
  + passengerCount : int
  + fee : double
  + requestType : string
}

class RideShareService {
  + pickUpTime : datetime
  + dropOffTime : datetime
  + pickUpLocation : string
  + dropOffLocation : string
  + rideDuration : string
  + distance : double
  + upfrontNegotiatedFee : double
}

class Customer {
  + name : string
}

class RideShareCustomer {
  + name : string
}

class RideHailCustomer {
  + name : string
}

Car "1" -- "*" Accident : experiences
Car "0..1" -- "1" Owner : owned by
Car "1" -- "*" RideHailService : provides
Car "1" -- "*" RideShareService : provides
RideHailService "*" -- "1" RideHailCustomer : lead customer
RideHailService "*" -- "1..6" Customer : passenger
RideShareService "*" -- "1..10" RideShareCustomer : passenger

@enduml

